<template>
  <q-page class="admin-page">
    <div v-if="auth.canPublish" class="admin-shell">
      <header class="admin-heading"><div><div class="admin-eyebrow">CONTROL CENTER</div><h1>站点 Dashboard</h1><p>管理账户、项目、版本和托管文件。</p></div><div class="admin-actions"><q-btn outline color="primary" icon="add" label="新建项目" to="/admin/projects/new" /><q-btn flat round icon="refresh" :loading="loading" @click="load" /></div></header>
      <q-banner v-if="error" rounded class="bg-red-1 text-red-9 q-mb-lg">{{ error }}</q-banner>
      <section class="dashboard-metrics"><article v-for="item in metrics" :key="item.label" class="dashboard-metric"><div class="metric-icon" :class="item.tone"><q-icon :name="item.icon" /></div><div><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.caption }}</small></div><q-icon name="trending_up" class="metric-trend" /></article></section>
      <section class="dashboard-grid">
        <q-card flat class="dashboard-card activity-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">OVERVIEW</div><h2>内容概览</h2></div><q-btn flat dense icon="more_horiz" /></q-card-section><q-card-section class="overview-bars"><div v-for="bar in overviewBars" :key="bar.label" class="overview-bar"><div class="overview-bar-label"><span>{{ bar.label }}</span><strong>{{ bar.value }}</strong></div><q-linear-progress rounded size="9px" :value="bar.ratio" :color="bar.color" track-color="grey-9" /></div></q-card-section></q-card>
        <q-card flat class="dashboard-card quick-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">QUICK ACTIONS</div><h2>快捷操作</h2></div></q-card-section><q-card-section class="quick-actions"><q-btn unelevated color="primary" text-color="dark" icon="add_box" label="创建项目" to="/admin/projects/new" /><q-btn v-if="auth.isAdmin" flat icon="people" label="管理账户" @click="tab = 'accounts'" /><q-btn flat icon="inventory_2" label="查看项目" @click="tab = 'projects'" /><q-btn flat icon="settings" label="账户设置" to="/account" /></q-card-section></q-card>
      </section>
      <section class="dashboard-grid q-mt-lg"><q-card flat class="dashboard-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">ENGAGEMENT</div><h2>真实使用统计</h2></div></q-card-section><q-card-section class="row q-col-gutter-lg"><div class="col-12 col-md-6"><div class="text-caption text-grey-6 q-mb-sm">下载排行</div><q-list dense separator><q-item v-for="item in overview.topDownloads" :key="`download-${item.projectSlug}`"><q-item-section>{{ item.projectSlug }}</q-item-section><q-item-section side>{{ item.count }}</q-item-section></q-item><q-item v-if="!overview.topDownloads.length"><q-item-section class="text-grey-6">暂无下载事件</q-item-section></q-item></q-list></div><div class="col-12 col-md-6"><div class="text-caption text-grey-6 q-mb-sm">收藏排行</div><q-list dense separator><q-item v-for="item in overview.topFavorites" :key="`favorite-${item.projectSlug}`"><q-item-section>{{ item.projectSlug }}</q-item-section><q-item-section side>{{ item.count }}</q-item-section></q-item><q-item v-if="!overview.topFavorites.length"><q-item-section class="text-grey-6">暂无收藏</q-item-section></q-item></q-list></div></q-card-section></q-card></section>
        <q-card flat class="dashboard-card records-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">CONTENT</div><h2>内容管理</h2></div><q-tabs v-model="tab" dense active-color="primary" indicator-color="primary"><q-tab name="projects" icon="inventory_2" label="项目" /><q-tab v-if="auth.isAdmin" name="reviews" icon="fact_check" label="审核队列" /><q-tab v-if="auth.isAdmin" name="accounts" icon="people" label="账户" /><q-tab v-if="auth.isAdmin" name="settings" icon="tune" label="站点设置" /></q-tabs></q-card-section><q-separator dark /><q-tab-panels v-model="tab" animated class="dashboard-panels"><q-tab-panel name="projects" class="q-pa-none"><q-table flat dark :rows="projects" :columns="projectColumns" row-key="id" :loading="loading" class="dashboard-table"><template #body-cell-title="props"><q-td :props="props"><div class="table-project"><q-avatar size="34px" color="primary" text-color="dark">{{ props.row.title?.slice(0, 1) }}</q-avatar><div><strong>{{ props.row.title }}</strong><small>{{ props.row.slug }} · {{ props.row.status }}</small></div></div></q-td></template><template #body-cell-actions="props"><q-td :props="props"><q-btn dense flat color="primary" label="编辑" :to="`/admin/projects/${props.row.slug}/edit`" /></q-td></template></q-table></q-tab-panel><q-tab-panel v-if="auth.isAdmin" name="reviews"><div class="row items-center q-mb-md"><div><h3 class="q-my-none">待审核内容</h3><div class="text-grey-6">需要人工处理的项目和文件。</div></div><q-space /><q-btn flat icon="refresh" @click="loadReviews" /></div><q-list bordered separator><q-item v-for="item in reviews" :key="`${item.type}-${item.id}`"><q-item-section><q-item-label>{{ item.title }}</q-item-label><q-item-label caption>{{ item.type }} · {{ item.slug }}</q-item-label></q-item-section><q-item-section side class="row q-gutter-sm"><q-btn dense color="positive" label="通过" @click="decide(item, 'approve')" /><q-btn dense outline color="negative" label="拒绝" @click="decide(item, 'reject')" /></q-item-section></q-item><q-item v-if="!reviews.length"><q-item-section class="text-grey-6">当前没有待处理项目。</q-item-section></q-item></q-list></q-tab-panel><q-tab-panel v-if="auth.isAdmin" name="accounts" class="q-pa-none"><q-table flat dark :rows="accounts" :columns="accountColumns" row-key="id" :loading="loading" class="dashboard-table"><template #body-cell-actions="props"><q-td :props="props" class="q-gutter-xs"><q-btn v-if="!props.row.verifiedAt" dense flat color="positive" label="通过审核" @click="approveAccount(props.row)" /><q-btn v-if="auth.isRoot" dense flat color="secondary" label="修改 UUID" @click="editMinecraftUuid(props.row)" /><q-btn dense flat color="primary" :disable="props.row.id === auth.account?.id || (props.row.role === 'root' && !auth.isRoot)" :label="nextRoleLabel(props.row.role)" @click="changeRole(props.row)" /><q-btn dense flat color="negative" :disable="props.row.id === auth.account?.id || (props.row.role === 'root' && !auth.isRoot)" label="删除" @click="removeAccount(props.row)" /></q-td></template></q-table></q-tab-panel><q-tab-panel v-if="auth.isAdmin" name="settings"><div v-if="settings" class="q-pa-md"><div class="text-h6 q-mb-sm">注册策略</div><q-toggle v-model="settings.registration.enabled" color="positive" label="开放注册" /><q-toggle v-model="settings.registration.requireInviteCode" class="q-ml-md" label="需要邀请码" /><q-toggle v-model="settings.registration.requireApproval" class="q-ml-md" label="注册后需要管理员审核" /><q-input v-if="settings.registration.requireInviteCode" v-model="registrationCodesText" outlined class="q-mt-sm q-mb-lg" label="邀请码（逗号分隔）" hint="邀请码目前可重复使用，最多保存 100 个。" /><div v-if="auth.isRoot" class="site-identity-settings q-mb-lg"><div class="text-h6 q-mb-sm">站点身份</div><div class="row q-col-gutter-md"><q-input v-model="settings.appearance.siteName" class="col-12 col-md-6" outlined label="站点名称" hint="显示在顶部导航和浏览器界面中。" /><q-input v-model="settings.appearance.siteIconUrl" class="col-12 col-md-6" outlined label="站点图标地址" hint="支持站内路径或 HTTPS 图片地址。" /></div><div v-if="settings.appearance.siteIconUrl" class="site-identity-preview q-mt-sm"><q-img :src="settings.appearance.siteIconUrl" fit="cover" width="42px" height="42px" :alt="settings.appearance.siteName" /><span>{{ settings.appearance.siteName }}</span></div></div><div class="text-h6 q-mb-sm">外观</div><q-toggle v-model="settings.appearance.roundedProjectIcons" color="positive" label="项目图标圆角" /><div class="text-caption text-grey-6 q-mb-lg">为项目图标图片添加圆角，适用于项目列表、详情及个人／组织页面。默认开启。</div><div class="text-h6 q-mb-md">内容审核策略</div><div class="row q-col-gutter-md"><q-select v-model="settings.moderation.projectCreation" class="col-12 col-md-6" outlined label="项目创建" :options="policyOptions" emit-value map-options /><q-select v-model="settings.moderation.fileSubmission" class="col-12 col-md-6" outlined label="文件提交" :options="policyOptions" emit-value map-options /></div><q-input v-model="settings.moderation.automatic.externalApiUrl" outlined label="自动审核 API URL" class="q-mt-md" /><div class="row q-col-gutter-md q-mt-sm"><q-select v-model="settings.moderation.automatic.failMode" class="col-12 col-md-4" outlined label="API 失败时" :options="[{ label: '转人工审核', value: 'manual' }, { label: '自动拒绝', value: 'reject' }]" emit-value map-options /><q-input v-model.number="settings.moderation.automatic.maxFileSize" class="col-12 col-md-4" type="number" outlined label="最大文件大小（字节）" /><q-input v-model="blockedExtensionsText" class="col-12 col-md-4" outlined label="禁止扩展名（逗号分隔）" /></div><div class="q-mt-sm"><q-toggle v-model="settings.moderation.automatic.requireHashes" label="要求 hash" /><q-toggle v-model="settings.moderation.automatic.requireSource" class="q-ml-md" label="要求下载源" /></div><div class="text-h6 q-mt-lg q-mb-sm">Mojang 官方同步</div><q-toggle v-model="settings.mojang.enabled" color="positive" label="启用 Microsoft/Mojang 同步" /><q-input v-model="settings.mojang.clientId" outlined class="q-mt-sm" label="Microsoft 应用 Client ID" hint="Azure 应用注册中的 Application (client) ID" /><q-select v-model="settings.mojang.tenant" outlined emit-value map-options label="租户类型" :options="[{ label: '个人账户 (consumers)', value: 'consumers' }, { label: '通用 (common)', value: 'common' }, { label: '组织 (organizations)', value: 'organizations' }]" /><div class="text-caption text-grey-7 q-mb-md">OAuth 加密密钥由服务器环境变量 OAUTH_ENCRYPTION_KEY 提供。</div><div class="text-h6 q-mt-lg q-mb-sm">Yggdrasil 认证</div><q-toggle v-model="settings.ygg.enabled" color="positive" label="启用 Ygg 代理" /><q-toggle v-model="settings.ygg.allowLocalAccounts" class="q-ml-md" label="允许站内账户登录" /><div v-if="auth.isRoot" class="row q-col-gutter-md q-mt-sm"><q-input v-model.number="settings.ygg.accessTokenTtlSeconds" type="number" min="300" max="86400" class="col-12 col-md-6" outlined label="Ygg Access Token 有效期（秒）" hint="300 到 86400 秒" /><q-input v-model.number="settings.ygg.refreshTokenTtlSeconds" type="number" min="3600" max="31536000" class="col-12 col-md-6" outlined label="Ygg Refresh Token 有效期（秒）" hint="当前用于生命周期策略校验" /></div><q-input v-model="yggUpstreamsText" type="textarea" autogrow outlined class="q-mt-sm" label="Ygg 上游（JSON）" hint="按 priority 从小到大尝试，例如 [{&quot;id&quot;:&quot;official&quot;,&quot;name&quot;:&quot;聚合服务&quot;,&quot;baseUrl&quot;:&quot;https://example.com/api/ygg&quot;,&quot;enabled&quot;:true,&quot;priority&quot;:10}]" /><div v-if="auth.isRoot" class="row q-gutter-sm q-mt-lg"><q-btn outline color="secondary" icon="download" label="导出数据库快照" @click="exportDatabase" /><q-file v-model="importBundleFile" accept="application/json,.modpost.json" class="database-import-file" label="选择快照导入" dense outlined @update:model-value="importDatabase" /></div><FormActions class="q-mt-md"><q-btn color="primary" label="保存站点设置" :loading="settingsSaving" @click="saveSettings" /></FormActions></div></q-tab-panel></q-tab-panels></q-card>
    </div>
  </q-page>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { SiteSettings } from '@andrea/contracts'
import { applySiteAppearance } from '../lib/site-settings'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { adminAccounts, adminOverview, adminProjects, deleteAccount, updateAccountRole, updateAccountVerification, updateMinecraftProfile, adminReviews, reviewProject, reviewFile, adminSettings, updateAdminSettings, type ReviewItem } from '../lib/admin'

import FormActions from '../components/FormActions.vue'

const router = useRouter(); const auth = useAuthStore(); const tab = ref('projects'); const loading = ref(false); const error = ref(''); const overview = ref({ accounts: 0, projects: 0, versions: 0, files: 0, downloads: 0, favorites: 0, topDownloads: [] as Array<{ projectSlug: string; count: number }>, topFavorites: [] as Array<{ projectSlug: string; count: number }> }); const accounts = ref<any[]>([]); const projects = ref<any[]>([]); const reviews = ref<ReviewItem[]>([]); const settings = ref<SiteSettings | null>(null); const settingsSaving = ref(false); const importBundleFile = ref<File | null>(null)
const metrics = computed(() => [{ label: '账户', value: overview.value.accounts, caption: '已注册账户', icon: 'people', tone: 'green' }, { label: '项目', value: overview.value.projects, caption: '公开项目', icon: 'inventory_2', tone: 'blue' }, { label: '版本', value: overview.value.versions, caption: '可下载版本', icon: 'new_releases', tone: 'purple' }, { label: '文件', value: overview.value.files, caption: '托管与外链文件', icon: 'cloud_download', tone: 'orange' }, { label: '下载', value: overview.value.downloads, caption: '真实下载事件', icon: 'download', tone: 'orange' }, { label: '收藏', value: overview.value.favorites, caption: '账户收藏记录', icon: 'favorite', tone: 'pink' }])
const overviewBars = computed(() => { const max = Math.max(overview.value.accounts, overview.value.projects, overview.value.versions, overview.value.files, 1); return [{ label: '项目', value: overview.value.projects, ratio: overview.value.projects / max, color: 'primary' }, { label: '版本', value: overview.value.versions, ratio: overview.value.versions / max, color: 'deep-purple-4' }, { label: '文件', value: overview.value.files, ratio: overview.value.files / max, color: 'orange-5' }, { label: '账户', value: overview.value.accounts, ratio: overview.value.accounts / max, color: 'light-blue-4' }] })
const accountColumns = [{ name: 'email', label: '邮箱', field: 'email', align: 'left' as const }, { name: 'role', label: '角色', field: 'role', align: 'left' as const }, { name: 'createdAt', label: '创建时间', field: 'createdAt', align: 'left' as const }, { name: 'actions', label: '操作', field: 'actions', align: 'right' as const }]; const projectColumns = [{ name: 'title', label: '项目', field: 'title', align: 'left' as const }, { name: 'type', label: '类型', field: 'type', align: 'left' as const }, { name: 'versions', label: '版本', field: (row: any) => row.versions?.length ?? 0, align: 'left' as const }, { name: 'actions', label: '操作', field: 'actions', align: 'right' as const }]
const policyOptions = [{ label: '无审核', value: 'none' }, { label: '自动审核', value: 'automatic' }, { label: '全人工审核', value: 'full' }]
const blockedExtensionsText = computed({ get: () => settings.value?.moderation.automatic.blockedExtensions.join(', ') ?? '', set: (value: string) => { if (settings.value) settings.value.moderation.automatic.blockedExtensions = value.split(',').map((item) => item.trim().toLowerCase().replace(/^\./u, '')).filter(Boolean) } }); const registrationCodesText = computed({ get: () => settings.value?.registration.inviteCodes.join(', ') ?? '', set: (value: string) => { if (settings.value) settings.value.registration.inviteCodes = value.split(',').map((item) => item.trim()).filter(Boolean) } })
const yggUpstreamsText = ref('')
const nextRole = (role: string): 'user' | 'developer' | 'admin' | 'root' => role === 'user' ? 'developer' : role === 'developer' ? 'admin' : 'user'
const nextRoleLabel = (role: string) => ({ user: '设为开发者', developer: '设为管理员', admin: '设为普通用户', root: 'root' }[role] ?? '设为开发者')
const changeRole = async (account: any) => { const role = nextRole(account.role); try { await updateAccountRole(account.id, role); account.role = role } catch { error.value = '账户角色更新失败。' } }; const approveAccount = async (account: any) => { try { const result = await updateAccountVerification(account.id, true); account.verifiedAt = result.verifiedAt } catch (cause) { error.value = cause instanceof Error ? cause.message : '账户审核失败。' } }; const editMinecraftUuid = async (account: any) => { const metadata = account.metadata ?? {}; const uuid = window.prompt('输入 32 位 Minecraft UUID（可带连字符）', metadata.minecraftUuid ?? ''); if (!uuid) return; const skinUrl = window.prompt('皮肤 URL（留空清除）', metadata.skinUrl ?? '') ?? ''; const capeUrl = window.prompt('披风 URL（留空清除）', metadata.capeUrl ?? '') ?? ''; try { const result = await updateMinecraftProfile(account.id, { uuid, skinUrl: skinUrl.trim() || null, capeUrl: capeUrl.trim() || null, source: 'local' }); account.metadata = { ...metadata, minecraftUuid: result.minecraftUuid, skinUrl: skinUrl.trim() || null, capeUrl: capeUrl.trim() || null, uuidSource: 'local' } } catch (cause) { error.value = cause instanceof Error ? cause.message : 'UUID 修改失败。' } }; const removeAccount = async (account: any) => { if (!window.confirm(`确定删除账户 ${account.email} 吗？该操作不可撤销。`)) return; try { await deleteAccount(account.id); accounts.value = accounts.value.filter((item) => item.id !== account.id); overview.value.accounts -= 1 } catch (cause) { error.value = cause instanceof Error ? cause.message : '账户删除失败。' } }
const loadReviews = async () => { try { reviews.value = (await adminReviews()).reviews } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法读取审核队列。' } }
const decide = async (item: ReviewItem, decision: 'approve' | 'reject') => { try { if (item.type === 'project') await reviewProject(item.slug, decision); else await reviewFile(item.id, decision); reviews.value = reviews.value.filter((candidate) => candidate.id !== item.id || candidate.type !== item.type) } catch (cause) { error.value = cause instanceof Error ? cause.message : '审核操作失败。' } }
const saveSettings = async () => { if (!settings.value) return; try { const parsed = JSON.parse(yggUpstreamsText.value); if (!Array.isArray(parsed)) throw new Error('Ygg 上游必须是 JSON 数组'); settings.value.ygg.upstreams = parsed } catch (cause) { error.value = cause instanceof Error ? `Ygg 上游配置无效：${cause.message}` : 'Ygg 上游配置无效。'; return } settingsSaving.value = true; try { settings.value = (await updateAdminSettings(settings.value)).settings; yggUpstreamsText.value = JSON.stringify(settings.value.ygg.upstreams, null, 2); applySiteAppearance(settings.value.appearance) } catch (cause) { error.value = cause instanceof Error ? cause.message : '站点设置保存失败。' } finally { settingsSaving.value = false } }
const exportDatabase = async () => { const password = window.prompt('设置快照加密密码（至少 12 个字符）'); if (!password) return; try { const response = await fetch('/api/v1/admin/database/export', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ password }) }); if (!response.ok) { const result = await response.json().catch(() => ({})); throw new Error(result.error?.message ?? '数据库快照导出失败') } const blob = new Blob([JSON.stringify(await response.json(), null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `andrea-modpost-${new Date().toISOString().slice(0, 10)}.modpost.json`; anchor.click(); URL.revokeObjectURL(url) } catch (cause) { error.value = cause instanceof Error ? cause.message : '数据库快照导出失败' } }
const importDatabase = async (value: File | File[] | null) => { const file = Array.isArray(value) ? value[0] : value; if (!file) return; if (!window.confirm('导入会合并账户、项目、组织和站点设置。确定继续吗？')) return; const password = window.prompt('输入快照加密密码'); if (!password) return; try { const bundle = JSON.parse(await file.text()); bundle.password = password; const response = await fetch('/api/v1/admin/database/import', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bundle) }); const result = await response.json(); if (!response.ok) throw new Error(result.error?.message ?? '数据库快照导入失败'); error.value = `导入完成：新增账户 ${result.summary.createdAccounts}，更新账户 ${result.summary.updatedAccounts}，新增项目 ${result.summary.createdProjects}，更新项目 ${result.summary.updatedProjects}` } catch (cause) { error.value = cause instanceof Error ? cause.message : '数据库快照导入失败' } finally { importBundleFile.value = null } }
const load = async () => { loading.value = true; error.value = ''; try { const [summary, projectResult] = await Promise.all([adminOverview(), adminProjects()]); overview.value = summary; projects.value = projectResult.projects; if (auth.isAdmin) { accounts.value = (await adminAccounts()).accounts; reviews.value = (await adminReviews()).reviews; settings.value = (await adminSettings()).settings; yggUpstreamsText.value = JSON.stringify(settings.value.ygg.upstreams, null, 2) } } catch (cause) { error.value = cause instanceof Error ? cause.message : '无法读取后台数据，请确认当前账户具有开发者或管理员权限。'; if (!auth.canPublish) await router.replace('/auth') } finally { loading.value = false } }
onMounted(async () => { await auth.load(); if (!auth.canPublish) return router.replace('/auth'); await load() })
</script>
